#include "kstationControllerStartupKeyboardRuntime.h"
#include "h8s/h8s.hpp"
#include <array>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <memory>
#include <vector>
struct Ref:H8SEmulator{void history(int r,int w){lastread=r;lastwrite=w;}};
struct Event{uint64_t at;uint32_t addr;uint8_t value;bool write;};
static bool mapped(uint32_t a){return (a>=0xc100&&a<0xc300)||(a>=0x1c100&&a<0x1c300)||(a>=0x84b2&&a<0x85b2)||a==0xffffc5||a==0xffffc7||a==0xffffd3;}
struct RBus:H8SDevice{Ref&c;std::array<uint8_t,4>keys{};std::array<Event,16>e{};unsigned n=0;explicit RBus(Ref&v):c(v){}uint8_t read(uint32_t a)override{auto v=a==0xffffc7?keys[(c.memory[0xffffd3]>>3)&3]:c.memory[a];e[n++]={c.cycles,a,v,false};return v;}void write(uint32_t a,uint8_t v)override{e[n++]={c.cycles,a,v,true};c.memory[a]=v;}};
struct NBus:kstation::ControllerResourceBus{std::array<uint8_t,4>keys{};std::array<Event,16>e{};unsigned n=0;bool enabled=false;bool mapped(uint32_t a)const override{return ::mapped(a);}uint8_t read(uint32_t a)override{auto v=a==0xffffc7?keys[(state_->memory[0xffffd3]>>3)&3]:state_->memory[a];if(enabled)e[n++]={state_->cycles,a,v,false};return v;}void write(uint32_t a,uint8_t v)override{if(enabled)e[n++]={state_->cycles,a,v,true};state_->memory[a]=v;}};
int main(int argc,char**argv){if(argc<2||argc>3)return 77;bool boot=argc==3;std::ifstream f(argv[1],std::ios::binary);std::vector<uint8_t>rom{std::istreambuf_iterator<char>(f),{}};if(rom.size()!=49728)return 1;auto c=std::make_unique<Ref>();auto d=std::make_unique<kstation::ControllerDeviceState>();c->loadmem(rom.data(),rom.size(),0);d->loadMemory(rom.data(),rom.size(),0);if(!boot)d->loadMemory(rom.data(),rom.size(),0x400000);RBus x(*c);NBus y;c->memmap(&x,0xc100,0x200);c->memmap(&x,0x1c100,0x200);c->memmap(&x,0x84b2,0x100);c->memmap(&x,0xffffc5,1);c->memmap(&x,0xffffc7,1);c->memmap(&x,0xffffd3,1);d->attachBus(&y);kstation::ControllerInterruptRuntime irq;kstation::ControllerStartupKeyboardRuntime rt;if((!boot&&!irq.bindVerifiedFirmware(*d,rom.data(),rom.size()))||!rt.bindBootResources(*d,rom.data(),rom.size())||(!boot&&!rt.bindMirroredFirmware(*d,rom.data(),rom.size())))return 2;y.enabled=true;uint64_t graphs=0,phases=0,events=0,shorts=0;for(unsigned kind=0;kind<6;++kind)for(unsigned flags=boot?128:0;flags<256;++flags){rt.reset();irq.reset();irq.setMask(flags&128?kstation::ControllerInterruptRuntime::Mask::Disabled:kstation::ControllerInterruptRuntime::Mask::Enabled);auto put=[&](uint32_t a,uint8_t v){c->memory[a]=d->memory[a]=v;};auto word=[&](uint32_t a,uint16_t v){put(a,v>>8);put(a+1,v);};for(unsigned i=0;i<0x200;++i)put(0xc100+i,uint8_t(i*17+flags));for(unsigned i=0;i<0x200;++i)put(0x1c100+i,uint8_t(i*31+flags));constexpr uint16_t indices[]={0,1,2,0x7e,0x7f,0x80,0xffff,0x20};uint16_t head=indices[flags&7],tail=indices[(flags>>3)&7];word(0xc144,head);word(0xc146,tail);word(0xc148+tail,0xa55a);for(unsigned i=0;i<4;++i){put(0xc1c8+i,uint8_t((i&1)?flags:~flags));x.keys[i]=y.keys[i]=uint8_t(flags^(i*73));}put(0xffffc5,0x82);put(0xffffd3,0x40);uint16_t arg=uint16_t(flags<<8|flags);constexpr uint32_t entries[]={0x44c,0x452,0x4aa,0x42c,0x466,0x534};c->pc=c->makepc(entries[kind]);c->setSP(0xffff10);for(unsigned i=0;i<4;++i)c->memory[0xffff10+i]=uint8_t(0x7000u>>(8*(3-i)));c->reg16(6)=int16_t(arg);c->ccr=uint8_t(flags);c->pending_irqs=d->pendingIrqs=0;c->pending_irqs_high=d->pendingIrqsHigh=0;c->interruptMode2=d->interruptMode2=false;c->cycles=d->cycles=100000;c->history(-1,-1);d->lastRead=d->lastWrite=-1;if(!rt.start(static_cast<kstation::ControllerStartupKeyboardRuntime::Kind>(kind),arg))return 3;for(unsigned k=0;rt.active();++k){if(k>100000){std::fprintf(stderr,"hang %x kind=%u\n",c->getPC(),kind);return 4;}auto at=uint32_t(c->getPC());x.n=y.n=0;auto cost=rt.nextClocks(*d,irq);if(!cost){std::fprintf(stderr,"cost %x kind=%u\n",at,kind);return 5;}if(phases%71==0){auto before=d->cycles;for(unsigned b=0;b<cost;++b){auto r=rt.advanceBefore(*d,irq,b);if(r.clocks||d->cycles!=before||y.n)return 6;++shorts;}}c->step();auto r=rt.advanceBefore(*d,irq,cost);if(!r.clocks||c->cycles!=d->cycles||x.n!=y.n){std::fprintf(stderr,"phase pc=%x kind=%u flags=%u clocks=%llu/%llu io=%u/%u\n",at,kind,flags,c->cycles,d->cycles,x.n,y.n);return 7;}for(unsigned i=0;i<x.n;++i)if(x.e[i].at!=y.e[i].at||x.e[i].addr!=y.e[i].addr||x.e[i].value!=y.e[i].value||x.e[i].write!=y.e[i].write){std::fprintf(stderr,"event pc=%x kind=%u addr=%x/%x value=%x/%x time=%llu/%llu\n",at,kind,x.e[i].addr,y.e[i].addr,x.e[i].value,y.e[i].value,x.e[i].at,y.e[i].at);return 8;}events+=x.n;++phases;}if(c->getPC()!=0x7000)return 9;if(kind==4&&rt.event()!=uint16_t(c->reg16(6))){std::fprintf(stderr,"event result %x/%x\n",rt.event(),uint16_t(c->reg16(6)));return 10;}if(std::memcmp(c->memory+0xc100,d->memory+0xc100,0x200)||std::memcmp(c->memory+0x1c100,d->memory+0x1c100,0x200)||c->memory[0xffffc5]!=d->memory[0xffffc5]||c->memory[0xffffd3]!=d->memory[0xffffd3])return 11;++graphs;}if(boot){y.enabled=false;d->loadMemory(rom.data(),rom.size(),0x400000);d->memory[0x40042c]^=1;if(rt.bindMirroredFirmware(*d,rom.data(),rom.size()))return 12;d->memory[0x40042c]^=1;if(!rt.bindMirroredFirmware(*d,rom.data(),rom.size()))return 13;}std::printf("{\"passed\":true,\"graphs\":%llu,\"phases\":%llu,\"events\":%llu,\"short_budgets\":%llu}\n",(unsigned long long)graphs,(unsigned long long)phases,(unsigned long long)events,(unsigned long long)shorts);}
